package dev.viewgo

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class ProtocolTest {

    /** Key and proof must match the Rust receiver byte for byte; regenerated by
     *  `cargo run --example vector` in receiver/. */
    @Test
    fun cryptoMatchesReceiverVector() {
        val salt = ByteArray(16) { 0 }
        val clientRandom = ByteArray(16) { 1 }
        val serverRandom = ByteArray(16) { 2 }
        val key = deriveKey("AB3D", salt, clientRandom, serverRandom)
        assertEquals(
            "d18e8faac03b548c88a01ec4204ca62e459c72e301b63cf0dbbfa4a20fe19949",
            key.toHex(),
        )
        assertEquals(
            "f32c964be074bf56da32739fa6f3c0cb62241a85a08dac4eb77dc8820583712d",
            proof(key, salt, clientRandom, serverRandom).toHex(),
        )
    }

    @Test
    fun codeNormalisation() {
        assertEquals("AB3D", normalizeCode("ab3-d"))
        assertEquals("AB30", normalizeCode("AB3O"))
        assertEquals("AB31", normalizeCode("AB3L"))
        assertNull(normalizeCode("AB3"))
        assertNull(normalizeCode("AB3D!"))
    }

    @Test
    fun manualTargetParsing() {
        assertEquals("192.168.1.24" to 47810, parseTarget(" 192.168.1.24 "))
        assertEquals("10.0.0.7" to 50000, parseTarget("10.0.0.7:50000"))
        assertEquals("192.168.1.24" to 47810, parseTarget("192.168.001.024"))

        assertNull(parseTarget(""))
        assertNull(parseTarget("192.168.1"))
        assertNull(parseTarget("192.168.1.256"))
        assertNull(parseTarget("192.168.1.24:0"))
        assertNull(parseTarget("192.168.1.24:70000"))
        assertNull(parseTarget("0.0.0.0"))
        assertNull(parseTarget("fe80::1"))
        assertNull(parseTarget("[fe80::1]:47810"))
        assertNull(parseTarget("laptop.local"))
    }

    private fun ByteArray.toHex() = joinToString("") { "%02x".format(it) }
}
